// === Tab: mySketch ===
// ポイントシェーダを召喚します。
// 術式構築

// ノイズフローやってみる
// ノイズに従って流れる
// 進行方向はノイズの2PI倍
// 一度に進む距離は0.2で, もとい可変で
// というか_SIZE/600にしようそうしよう
// んでスケールについては・・_SIZEで割ればいいよね。そうしよう。
// で、ポイントサイズも、_SIZE/1200にするかこっちは。

// 係数変えると面白いので1～8で可変にする

// さてと
// テストもOKみたいだし等高線いってみるか・・（別のプログラムで）
// だってノイズを方向に変換するだけじゃ物足りないし
// ただまあそれでもきれいなのよね・・

// 球面作ろうとしたけど失敗。

// 参考：https://openprocessing.org/sketch/157576

let count = 0;
let _SIZE;
let _POINT_SIZE;
let _SPEED;
let _NOISE_SCALE;
let _POINT_NUM; // 今回はサイズから決める。1.6倍でいく。上下の・・うん。
// 色はノイズで。
let _NOISE_SEED; // ノイズシード
let _X_DIFF; // xのずらし
let _Y_DIFF; // yのずらし・・ずらさないと対称になっちゃうっぽい
let _COEFF; // noise()*TAUに掛ける係数(1～8)
const LIFE_COUNT_MAX = 300;
let positions ;
let lifes;
// 第3引数で色を決める、色は適当にRGBのどれか、ランダムで最初に決まる、それ±10くらいで。整数で足す。
// 今回は方向はパスで。整数だけ送る感じ・・てかもういっそHSBの値だけ送ろう。sat値はカウントで色付けたり消したりする感じで。
// 黒背景でbg0,9使う。

let _gl, gl;
let pBuf;
let myPointShader;
let vsPoint =
"precision mediump float;" +
// ↑これがないと両方でuCount使えなくてエラーになる
"attribute vec3 aPosition;" +
"uniform float uPointSize;" +
"uniform float uCount;" +
"const float TAU = 6.28318;" +
"const float PI = 3.14159;"+
"varying float vStrokeWeight;" +
"varying vec3 vPosition;" +
"varying vec4 vMaterialColor;" +
"varying float vHue;" +
"uniform mat4 uModelViewMatrix;" +
"uniform mat4 uProjectionMatrix;" +
"void main() {" +
"  vec3 p = aPosition;" +

// 点の位置をいじるパート
"  vHue = p.z;" + // 色情報.0～1で。
"  p.z = 0.0;" + // 色情報取り出したら消す。

// 設定
"  vec4 positionVec4 =  vec4(p, 1.0);" +

"  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;" +

// サイズをいじる
"  gl_PointSize = uPointSize;" +
"  vStrokeWeight = uPointSize;" +
"}";

let fsPoint =
"precision mediump float;" +
"precision mediump int;" +
"uniform vec4 uMaterialColor;" +
"uniform float uCount;" +
"const float TAU = 6.28318;" +
"varying float vStrokeWeight;" +
"varying vec3 vPosition;" +
"varying float vHue;" +
// getRGB,参上！
"vec3 getRGB(float h, float s, float b){" +
"    vec3 c = vec3(h, s, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +

"void main(){" +
"  float mask = 0.0;" +

// make a circular mask using the gl_PointCoord (goes from 0 - 1 on a point)
// might be able to get a nicer edge on big strokeweights with smoothstep but slightly less performant

"  mask = step(0.98, length(gl_PointCoord * 2.0 - 1.0));" +

// if strokeWeight is 1 or less lets just draw a square
// this prevents weird artifacting from carving circles when our points are really small
// if strokeWeight is larger than 1, we just use it as is

"  mask = mix(0.0, mask, clamp(floor(vStrokeWeight - 0.5),0.0,1.0));" +

// throw away the borders of the mask
// otherwise we get weird alpha blending issues

"  if(mask > 0.98){" +
"    discard;" +
"  }" +

// 色をいじるパート
// 情報使わないの勿体ない気もするけど今回は時間ないのでシンプルに。
// bltいじると等高線であることがわかりやすい
"  float hue = vHue;" +
"  float sat = 0.5 + 0.5 * cos(TAU * uCount * (0.01 + vHue * 0.002));" +
"  float blt = (abs(fract(vHue * 20.0)-0.5) < 0.05 ? 1.0 : 0.0);" +
"  blt = 1.0 - pow(0.5 + 0.5 * sin(vHue * 20.0 * TAU), 4.0);" +
"  vec3 col = getRGB(hue, sat, blt);" +
"  gl_FragColor = vec4(col, 1.0);" +
"}";

let bg;

function setup(){
	_gl = createCanvas(4/3*windowHeight, windowHeight, WEBGL);
	bg = createGraphics(width, height);
	_SIZE = max(width, height);
	_POINT_SIZE = _SIZE / 300;
	_SPEED = _SIZE / 300;
	_NOISE_SCALE = _SIZE * 0.8;
	_POINT_NUM = floor(_SIZE * 3.5);
	pixelDensity(1);
	positions = new Float32Array(_POINT_NUM * 3); // たとえば600なら960くらい。
	lifes = new Float32Array(_POINT_NUM); // 600カウントで移動する感じで
	gl = _gl.GL;
	myPointShader = createShader(vsPoint, fsPoint);
	myPointShader.isPointShader = () => true;
	_gl.userPointShader = myPointShader;

	initialize(); // 初期化処理
	background(0);
}

function initialize(){
	//clear();
	//bg.clear();
	background(0);
	_COEFF = 1.0 + 7.0 * Math.random(); // 係数
	_NOISE_SEED = Math.random() * 9999; // シード値
	_X_DIFF = max(width, height) * (1 + Math.random());
	_Y_DIFF = max(width, height) * (1 + Math.random());
	for(let i = 0; i < _POINT_NUM; i++){
		positions[i * 3] = (Math.random() - 0.5) * width;
		positions[i * 3 + 1] = (Math.random() - 0.5) * height;
		positions[i * 3 + 2] = 0;
		lifes[i] = LIFE_COUNT_MAX; // 寿命。画面外に出た場合はカウントによらずリセット。
	}
}

// パターンチェンジは全体をクリアして
// もちろん背景もクリアして
// positionsも再設定して
// _MAIN_COLORと_COEFFを再設定する
function draw(){
	let start = millis();
  //background(0);
	//image(bg, -width * 0.5, -height * 0.5);
	resetShader();
	stroke(0);
	strokeWeight(_POINT_SIZE);
	noFill();
	shader(myPointShader);
	myPointShader.setUniform("uCount", count);
	myPoints(_POINT_NUM);
	count++;
	//bg.image(_gl, 0, 0);
	//bg.background(0, 6);
	let end = millis();
	//if(count % 60 == 0){ console.log((end-start)*60/999); }
}

// 点を用意するだけ！
function myPoints(num){
	const gId = `myPoints|${num}`;
  if(!_gl.geometryInHash(gId)){
    const _geom = new p5.Geometry();
    let v = createVector();
    for(let i = 0; i < num; i++){
      _geom.vertices.push(v.set(positions[i * 3], positions[i * 3 + 1], positions[i * 3 + 2]).copy());
    }
    pBuf = _gl.createBuffers(gId, _geom);
  }
	myDrawPoints();
}

// さてと。メインディッシュ。
function myDrawPoints(){
  _gl._setPointUniforms(myPointShader);

  _gl._bindBuffer(_gl.immediateMode.buffers.point, gl.ARRAY_BUFFER, _gl._vToNArray(pBuf.model.vertices), Float32Array, gl.DYNAMIC_DRAW);

  myPointShader.enableAttrib(myPointShader.attributes.aPosition, 3);

	setPositions();
	gl.bufferSubData(gl.ARRAY_BUFFER, 0, positions);

  gl.drawArrays(gl.Points, 0, pBuf.model.vertices.length);
  myPointShader.unbindShader();
}

// 土台が一応できたので
// ロジック
// まずノイズを計算して
// それにTAUを掛けて方向とし
// スピードを足す
// 以上。それだけ。
// 画面外に出たら再配置する。
// いけるか？？

// 変えるのはここだけ・・のはず（ノイズで着色するなら別だけど）
function setPositions(){
	let x, y, n, dx, dy, direction, u, v;
	for(let i = 0; i < _POINT_NUM; i++){
		x = positions[i * 3];
		y = positions[i * 3 + 1];
		n = noise((x + _X_DIFF) / _NOISE_SCALE, (y + _Y_DIFF) / _NOISE_SCALE, _NOISE_SEED);
		dx = noise((x + _X_DIFF + 1) / _NOISE_SCALE, (y + _Y_DIFF) / _NOISE_SCALE, _NOISE_SEED) - n;
		dy = noise((x + _X_DIFF) / _NOISE_SCALE, (y + _Y_DIFF + 1) / _NOISE_SCALE, _NOISE_SEED) - n;
		direction = atan2(dx, -dy);
		u = _SPEED * cos(direction);
		v = _SPEED * sin(direction);
		if(abs(x + u) > width * 0.5 || abs(y + v) > height * 0.5){
			x = width * (Math.random() - 0.5);
			y = height * (Math.random() - 0.5);
			lifes[i] = LIFE_COUNT_MAX;
		}else{
			x += u;
			y += v;
		}
		lifes[i]--;
		if(lifes[i] === 0){
			x = width * (Math.random() - 0.5);
			y = height * (Math.random() - 0.5);
			lifes[i] = LIFE_COUNT_MAX;
		}
		positions[i * 3] = x;
		positions[i * 3 + 1] = y;
		positions[i * 3 + 2] = n * 2.0;
	}
}

function mouseClicked(){
	initialize();
}

